body {width: 100vw;height: 100vh;margin: 0;overflow: hidden;}.radial-menu-component {position: absolute;left: 40vw;top: 20vh;}.radial-menu-component-two {position: absolute;left: 40vw;top: 20vh;}.guic-radial-menu {border: 2px solid #000;border-radius: 50%;}[data-dark-mode] .guic-radial-menu {border: 2px solid #ccc;}.guic-radial-menu-items {background-color: rgba(102, 102, 102, 0.5);}[data-dark-mode] .guic-radial-menu-items {background-color: rgba(102, 102, 102, 0.2);}.guic-radial-menu-center-bullseye {background-color: #000;}[data-dark-mode] .guic-radial-menu-center-bullseye {background-color: #ccc;}.guic-radial-menu-center-text {color: #fff;}[data-dark-mode] .guic-radial-menu-center-text {color: #000;}.guic-radial-menu-center-bullseye-outer {border-color: #000;}[data-dark-mode] .guic-radial-menu-center-bullseye-outer {border-color: #ccc;}.guic-radial-menu-selector-bg-2 {border: 8.25vh solid rgba(0, 0, 0, 0.5);}[data-dark-mode] .guic-radial-menu-selector-bg-2 {border: 8.25vh solid rgba(255, 255, 255, 0.75);}.page-wrapper {height: 45vh;}.radial-menu-center-bullseye {position: absolute;width: 80%;height: 80%;background-color: #4a9cc5;border-radius: 50%;}.radial-menu-center-image {position: absolute;width: 80%;height: 80%;background-image: url('https://CoherentLabs.github.io/GameUIComponents//images/GameMessage_AchievmentIcon.png');background-size: cover;background-repeat: no-repeat;}.radial-menu-center {position: absolute;width: 23.7vh;height: 23.7vh;display: flex;justify-content: center;align-items: center;}Press Shift key to open a radial menu with custom center part
Press Space key to open the default radial menu
